import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,writeFile,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';
async function scenario(fn){
  const server=await testServer();const dir=await mkdtemp(tmpdir()+'/crew-issue-cli-');
  try{
    const api=server.agent();const auth=await api('POST','/auth/signup',{name:'CLI Owner',email:'cli@example.test',password:'correct-horse-battery'});
    const org=(await api('POST','/orgs',{name:'CLI org'})).data.organization;
    const project=(await api('POST','/orgs/'+org.id+'/projects',{key:'CLI',name:'CLI project'})).data.project;
    await writeFile(dir+'/config.json',JSON.stringify({url:server.url,cookie:auth.cookie}));
    const cli=args=>new Promise((resolve,reject)=>{
      const child=spawn(process.execPath,[fileURLToPath(new URL('../bin/crew.js',import.meta.url)),...args,'--config',dir+'/config.json','--json']);let stdout='',stderr='';
      const timer=setTimeout(()=>{child.kill('SIGKILL');reject(new Error('CLI deadline exceeded'));},10000);
      child.stdout.on('data',data=>stdout+=data);child.stderr.on('data',data=>stderr+=data);child.on('error',reject);child.on('close',code=>{clearTimeout(timer);resolve({code,stdout,stderr,data:stdout.trim()?JSON.parse(stdout):null});});
    });
    await fn({cli,api,project});
  }finally{await server.close();await rm(dir,{recursive:true,force:true});}
}
test('actual issue CLI creates edits and reads every supplied field',()=>scenario(async({cli,project})=>{
  const created=await cli(['issue','create',project.id,'--title','CLI issue','--description','Markdown **text**','--priority','2','--estimate','3.5','--due','2028-02-29']);
  assert.equal(created.code,0,created.stderr);const id=created.data.issue.id;assert.equal(created.data.issue.key,'CLI-1');assert.equal(created.data.issue.estimate,3.5);
  const edited=await cli(['issue','edit',id,'--title','Edited','--estimate','none']);assert.equal(edited.code,0,edited.stderr);assert.equal(edited.data.issue.estimate,null);
  const shown=await cli(['issue','show',id]);assert.equal(shown.data.issue.title,'Edited');assert.equal(shown.data.issue.description,'Markdown **text**');
}));
test('actual issue CLI filters paginates and manages labels',()=>scenario(async({cli,project})=>{
  const label=await cli(['issue','label-create',project.id,'--name','Release','--color','#123456']);assert.equal(label.code,0,label.stderr);
  await cli(['issue','create',project.id,'--title','Ship','--labels',label.data.label.id]);
  const list=await cli(['issue','list',project.id,'--label',label.data.label.id,'--limit','1']);assert.equal(list.code,0,list.stderr);assert.equal(list.data.items[0].title,'Ship');
  const changed=await cli(['issue','label-edit',label.data.label.id,'--name','Milestone']);assert.equal(changed.code,0,changed.stderr);
  const labels=await cli(['issue','labels',project.id]);assert.equal(labels.data.items[0].name,'Milestone');
}));
test('actual issue CLI rejects invalid edits and requires explicit deletion',()=>scenario(async({cli,project})=>{
  const created=await cli(['issue','create',project.id,'--title','Keep']);const id=created.data.issue.id;
  assert.equal((await cli(['issue','edit',id,'--priority','9'])).code,1);
  assert.equal((await cli(['issue','delete',id])).code,1);
  assert.equal((await cli(['issue','show',id])).code,0);
  assert.equal((await cli(['issue','delete',id,'--yes'])).code,0);
  assert.equal((await cli(['issue','show',id])).code,1);
}));

test('actual issue CLI comments previews mentions and all relation actions persist',()=>scenario(async({cli,project})=>{
  const first=(await cli(['issue','create',project.id,'--title','Discuss'])).data.issue;
  const second=(await cli(['issue','create',project.id,'--title','Related'])).data.issue;
  const comment=await cli(['issue','comment',first.id,'--body','**Ship** <script>bad</script>']);assert.equal(comment.code,0,comment.stderr);assert.ok(comment.data.comment.html.includes('&lt;script&gt;'));
  assert.equal((await cli(['issue','comment-edit',comment.data.comment.id,'--body','Edited comment'])).code,0);
  assert.equal((await cli(['issue','comments',first.id])).data.items[0].body,'Edited comment');
  for(const kind of ['blocks','duplicates','relates']){
    const relation=await cli(['issue','relate',first.id,'--target',second.id,'--kind',kind]);assert.equal(relation.code,0,relation.stderr);
    assert.equal((await cli(['issue','relations',first.id])).data.items.some(item=>item.kind===kind),true);
    assert.equal((await cli(['issue','unrelate',relation.data.relation.id,'--yes'])).code,0);
  }
  assert.equal((await cli(['issue','comment-delete',comment.data.comment.id,'--yes'])).code,0);assert.deepEqual((await cli(['issue','comments',first.id])).data.items,[]);
}));

test('actual CLI discovers candidates pages and child references without opaque ID entry',()=>scenario(async({cli,api,project})=>{
  const parent=(await api('POST','/projects/'+project.id+'/issues',{title:'Parent'})).data.issue;
  const child=(await api('POST','/projects/'+project.id+'/issues',{title:'Child',parentId:parent.id})).data.issue;
  const options=await cli(['issue','options',project.id,'--type','parents','--issue',child.id,'--query','Parent','--limit','1']);assert.equal(options.code,0,options.stderr);assert.equal(options.data.items[0].id,parent.id);
  const children=await cli(['issue','children',parent.id]);assert.equal(children.code,0,children.stderr);assert.deepEqual(children.data.items.map(item=>item.id),[child.id]);
  const excluded=await cli(['issue','options',project.id,'--type','parents','--issue',parent.id,'--selected',child.id]);assert.equal(excluded.data.total,0);
}));
test('actual CLI preconditions retain changed server fields and reject stale issue comment and label updates',()=>scenario(async({cli,api,project})=>{
  const issue=(await cli(['issue','create',project.id,'--title','Original'])).data.issue;
  await api('PATCH','/issues/'+issue.id,{description:'External value'});
  const stale=await cli(['issue','edit',issue.id,'--title','Local','--if-revision',issue.revision]);assert.equal(stale.code,1);assert.match(stale.stderr,/changed while you were editing/);
  const latest=(await cli(['issue','show',issue.id])).data.issue;
  const saved=await cli(['issue','edit',issue.id,'--title','Local','--if-revision',latest.revision]);assert.equal(saved.code,0,saved.stderr);assert.equal(saved.data.issue.description,'External value');
  const comment=(await cli(['issue','comment',issue.id,'--body','Initial comment'])).data.comment;
  const shown=(await cli(['issue','comment-show',comment.id])).data.comment;assert.equal(shown.revision,comment.revision);
  await api('PATCH','/comments/'+comment.id,{body:'External comment'});
  assert.equal((await cli(['issue','comment-edit',comment.id,'--body','Stale comment','--if-revision',comment.revision])).code,1);
  const label=(await cli(['issue','label-create',project.id,'--name','Original label'])).data.label;
  assert.equal((await cli(['issue','label-show',label.id])).data.label.revision,label.revision);
  await api('PATCH','/labels/'+label.id,{name:'External label'});
  assert.equal((await cli(['issue','label-edit',label.id,'--name','Stale label','--if-revision',label.revision])).code,1);
}));

import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
import {createIssue} from '../src/modules/work/issues.js';
async function fixture(fn) {
  const server=await testServer();
  try {
    const request=server.agent();
    const user=(await request('POST','/auth/signup',{name:'Owner',email:'depth@example.test',password:'correct-horse-battery'})).data.user;
    const org=(await request('POST','/orgs',{name:'Depth organization'})).data.organization;
    const project=(await request('POST','/orgs/'+org.id+'/projects',{key:'DEP',name:'Depth project'})).data.project;
    const create=body=>createIssue(server.ctx,{user},project.id,body);
    const options=(type,extra='')=>request('GET','/projects/'+project.id+'/issue-options?type='+type+extra);
    await fn({server,request,user,org,project,create,options});
  }finally{await server.close();}
}
test('parent candidate pages reach beyond 200 and selected lookup resolves independently of search',()=>fixture(async({create,options})=>{
  const first=create({title:'Older than first page'});for(let n=0;n<210;n++)create({title:'Candidate '+n});
  let cursor='',found=false,total=0;
  do{const result=await options('parents','&limit=20'+(cursor?'&cursor='+encodeURIComponent(cursor):''));assert.equal(result.status,200);assert.equal(result.data.total,211);total+=result.data.items.length;found ||= result.data.items.some(item=>item.id===first.id);cursor=result.data.nextCursor;}while(cursor);
  assert.equal(total,211);assert.equal(found,true);
  const selected=await options('parents','&q=does-not-match&id='+first.id);assert.deepEqual(selected.data.items.map(item=>item.id),[first.id]);
}));
test('parent options exclude self and every descendant before matching and pagination',()=>fixture(async({create,options,request,project})=>{
  const root=create({title:'Root'});let node=root;for(let n=0;n<205;n++)node=create({title:'Descendant '+n,parentId:node.id});
  const unrelated=create({title:'Eligible parent'});
  const page=await options('parents','&issueId='+root.id+'&limit=1');assert.deepEqual(page.data.items.map(item=>item.id),[unrelated.id]);assert.equal(page.data.total,1);assert.equal(page.data.nextCursor,null);
  assert.equal((await options('parents','&issueId='+root.id+'&id='+node.id)).data.total,0);
  assert.equal((await request('GET','/projects/'+project.id+'/issues?parentId='+root.id)).data.items.length,1);
}));
test('labels and visible member search reach later records while hiding ungranted guests',()=>fixture(async({server,user,org,project,options,request})=>{
  const db=server.ctx.db,time=server.ctx.now();
  server.ctx.transaction(()=>{
    for(let n=0;n<212;n++){
      const id='member-'+String(n).padStart(3,'0');
      db.prepare('INSERT INTO users (id,email,name,password_hash,created_at,updated_at) SELECT ?,?,?,password_hash,?,? FROM users WHERE id=?').run(id,id+'@example.test','Person '+String(n).padStart(3,'0'),time,time,user.id);
      db.prepare('INSERT INTO memberships (org_id,user_id,role,created_at,updated_at) VALUES (?,?,?,?,?)').run(org.id,id,n===211?'guest':'member',time,time);
      db.prepare('INSERT INTO labels VALUES (?,?,?,?,?,?)').run('label-'+n,project.id,'Label '+String(n).padStart(3,'0'),'#123456',time,time);
    }
  });
  const users=await options('users','&q=Person%20210');assert.equal(users.data.items[0].id,'member-210');assert.equal(users.data.total,1);
  assert.equal((await options('users','&q=Person%20211')).data.total,0);
  await request('POST','/projects/'+project.id+'/guests',{userId:'member-211'});
  assert.equal((await options('users','&id=member-211')).data.total,1);
  const label=await options('labels','&q=Label%20211');assert.equal(label.data.items[0].id,'label-211');
  const later=(await request('GET','/projects/'+project.id+'/labels?q=211')).data;assert.equal(later.items[0].id,'label-211');
}));
test('work-only tokens and granted guest mention flows need no insight permission',()=>fixture(async({request,options,server,org,project})=>{
  const token=(await request('POST','/tokens',{name:'Issue editor',scopes:['issue:write','project:read']})).data.token;
  const response=await request('GET','/projects/'+project.id+'/issue-options?type=users&permission=issue%3Awrite',undefined,{authorization:'Bearer '+token});assert.equal(response.status,200);
  const read=(await request('POST','/tokens',{name:'Read only',scopes:['project:read']})).data.token;
  assert.equal((await request('GET','/projects/'+project.id+'/issue-options?type=parents&permission=issue%3Awrite',undefined,{authorization:'Bearer '+read})).status,403);
  const guest=server.agent(),guestUser=(await guest('POST','/auth/signup',{name:'Visible Guest',email:'guest-depth@example.test',password:'correct-horse-battery'})).data.user;
  await request('POST','/orgs/'+org.id+'/members',{userId:guestUser.id,role:'guest'});
  assert.equal((await guest('GET','/projects/'+project.id+'/issue-options?type=users&permission=comment%3Awrite')).status,403);
  await request('POST','/projects/'+project.id+'/guests',{userId:guestUser.id});
  const visible=await guest('GET','/projects/'+project.id+'/issue-options?type=users&permission=comment%3Awrite');assert.equal(visible.status,200);assert.ok(visible.data.items.some(item=>item.id===guestUser.id));
  assert.equal((await guest('GET','/projects/'+project.id+'/issue-options?type=relations')).status,403);
}));
test('relation lookup crosses eligible same-org projects and excludes self archived and other-org issues',()=>fixture(async({request,org,create,options,project})=>{
  const source=create({title:'Source'});
  const cross=(await request('POST','/orgs/'+org.id+'/projects',{key:'CROSS',name:'Cross project'})).data.project;
  const target=(await request('POST','/projects/'+cross.id+'/issues',{title:'Cross target'})).data.issue;
  const otherOrg=(await request('POST','/orgs',{name:'Other organization'})).data.organization;
  const other=(await request('POST','/orgs/'+otherOrg.id+'/projects',{key:'HIDE',name:'Other project'})).data.project;
  await request('POST','/projects/'+other.id+'/issues',{title:'Other organization target'});
  let result=await options('relations','&issueId='+source.id);assert.deepEqual(result.data.items.map(item=>item.id),[target.id]);
  assert.equal((await request('POST','/issues/'+source.id+'/relations',{kind:'blocks',targetIssueId:target.id})).status,201);
  const inverse=(await request('GET','/issues/'+target.id+'/relations')).data.items[0];assert.equal(inverse.caption,'blocked by');assert.equal(inverse.relatedIssue.id,source.id);
  await request('PATCH','/projects/'+cross.id,{archived:true});result=await options('relations','&issueId='+source.id+'&id='+target.id);assert.equal(result.data.total,0);
  assert.equal((await options('parents','&issueId='+target.id)).status,422);
}));
test('relation lists hide inaccessible endpoints before all cursor pages and counts',()=>fixture(async({request,server,org,project,create})=>{
  const source=create({title:'Source'}),visible=[];
  const privateProject=(await request('POST','/orgs/'+org.id+'/projects',{key:'PRIV',name:'Private project'})).data.project;
  for(let n=0;n<51;n++){const item=create({title:'Related '+n});visible.push(item.id);await request('POST','/issues/'+source.id+'/relations',{kind:'relates',targetIssueId:item.id});}
  const hidden=(await request('POST','/projects/'+privateProject.id+'/issues',{title:'Hidden relation'})).data.issue;
  await request('POST','/issues/'+source.id+'/relations',{kind:'relates',targetIssueId:hidden.id});
  const guest=server.agent(),person=(await guest('POST','/auth/signup',{name:'Reader',email:'reader-depth@example.test',password:'correct-horse-battery'})).data.user;
  await request('POST','/orgs/'+org.id+'/members',{userId:person.id,role:'guest'});await request('POST','/projects/'+project.id+'/guests',{userId:person.id});
  let cursor='',ids=[];do{const page=(await guest('GET','/issues/'+source.id+'/relations?limit=20'+(cursor?'&cursor='+encodeURIComponent(cursor):''))).data;ids.push(...page.items.map(row=>row.relatedIssue.id));cursor=page.nextCursor;}while(cursor);
  assert.equal(ids.length,51);assert.deepEqual(new Set(ids),new Set(visible));assert.ok(!ids.includes(hidden.id));
}));
test('issue revision rejects stale saves without mutation events even when timestamps repeat',()=>fixture(async({server,request,create})=>{
  server.ctx.now=()=> '2026-10-16T00:00:00.000Z';const issue=create({title:'Original'}),events=[];server.ctx.bus.subscribe(event=>events.push(event));
  const changed=await request('PATCH','/issues/'+issue.id,{description:'External',expectedRevision:issue.revision});assert.equal(changed.status,200);assert.notEqual(changed.data.issue.revision,issue.revision);
  const stale=await request('PATCH','/issues/'+issue.id,{title:'Local',expectedRevision:issue.revision});assert.equal(stale.status,409);assert.equal(stale.data.error.details.current.description,'External');assert.equal(events.filter(event=>event.entityType==='issue').length,1);
  const resolved=await request('PATCH','/issues/'+issue.id,{title:'Local',expectedRevision:changed.data.issue.revision});assert.equal(resolved.data.issue.description,'External');assert.equal(resolved.data.issue.title,'Local');
  assert.equal((await request('PATCH','/issues/'+issue.id,{title:'Bad',expectedRevision:1})).status,422);
}));
test('comments and labels expose authorized snapshots and reject stale drafts',()=>fixture(async({request,server,create,project})=>{
  const issue=create({title:'Comment issue'}),comment=(await request('POST','/issues/'+issue.id+'/comments',{body:'Original'})).data.comment;
  const label=(await request('POST','/projects/'+project.id+'/labels',{name:'Original'})).data.label;
  for(const [route,field,record,patch,next] of [['/comments/','comment',comment,{body:'New'},{body:'Stale'}],['/labels/','label',label,{name:'New'},{name:'Stale'}]]){
    assert.deepEqual((await request('GET',route+record.id)).data[field],record);
    const update=await request('PATCH',route+record.id,{...patch,expectedRevision:record.revision});assert.equal(update.status,200);
    const conflict=await request('PATCH',route+record.id,{...next,expectedRevision:record.revision});assert.equal(conflict.status,409);assert.deepEqual(conflict.data.error.details.current,update.data[field]);
    const stranger=server.agent();assert.equal((await stranger('GET',route+record.id)).status,401);
  }
}));
test('candidate validation and archived mutation guards retain stable errors without leaked choices',()=>fixture(async({request,project,options,create})=>{
  const issue=create({title:'Archive source'});
  for(const suffix of ['&limit=201','&cursor=invalid','&q='+encodeURIComponent('x'.repeat(201))])assert.equal((await options('parents',suffix)).status,422);
  assert.equal((await options('unknown')).status,422);
  await request('PATCH','/projects/'+project.id,{archived:true});assert.equal((await options('relations','&issueId='+issue.id)).status,422);
  assert.equal((await request('PATCH','/issues/'+issue.id,{title:'Retained draft',expectedRevision:issue.revision})).status,409);
}));
